// What the kobold and the people can do to a board, as one kind of
// request each (the kobold's tools and the page's buttons both come here),
// and what each did, in a line.
import { Refused } from "../../refused.js";
import { agreed, linked, newId, thingOf, unlinked, withOptions, withoutThing, withThing, } from "./board-things.js";
const fresh = (by) => ({ agreed: false, place: null, by });
// A thing added, with its arrow from the thing it follows when one is named
// (an unknown one is said, and the thing is still added).
function added(board, thing, from = {}) {
    const next = withThing(board, thing);
    if (!from.from)
        return { board: next, said: `Added ${thing.id}.` };
    if (!board.things.some((one) => one.id === from.from))
        return {
            board: next,
            said: `Added ${thing.id}; there is no ${from.from} to link it from.`,
        };
    return {
        board: linked(next, from.from, thing.id, from.label?.trim() ?? ""),
        said: `Added ${thing.id}, linked from ${from.from}.`,
    };
}
// A choice's options, changed: the ones to take off (not one with a
// prototype), then the ones added or changed.
function choiceOptions(board, options, act) {
    const off = act.removeOptions ?? [];
    if (board.things.some((one) => one.kind === "prototype" && off.includes(one.key)))
        throw new Refused("An option with a prototype stays.");
    return withOptions(options.filter((one) => !off.includes(one.key)), act.options ?? []);
}
function changed(board, act) {
    const thing = thingOf(board, act.id);
    const next = { ...thing };
    if (next.kind === "note" && act.text)
        next.text = act.text.trim();
    if ((next.kind === "diagram" ||
        next.kind === "choice" ||
        next.kind === "picture") &&
        act.title)
        next.title = act.title.trim();
    if (next.kind === "diagram" && act.diagram)
        next.diagram = act.diagram;
    if (next.kind === "choice") {
        next.options = choiceOptions(board, next.options, act);
        const recommended = recommendedOf(next.options, act.recommended);
        if (recommended)
            next.recommended = recommended;
        else if (!next.options.some((one) => one.key === next.recommended))
            delete next.recommended;
    }
    return { board: withThing(board, next), said: `Changed ${act.id}.` };
}
function newChoice(board, act, by) {
    const options = withOptions([], act.options);
    const recommended = recommendedOf(options, act.recommended);
    return {
        id: newId(board, "choice"),
        kind: "choice",
        ...fresh(by),
        title: act.title.trim(),
        options,
        chosen: null,
        ...(recommended ? { recommended } : {}),
    };
}
// The option recommended, by its letter; one the choice has not refused.
function recommendedOf(options, key) {
    const letter = key?.trim().toUpperCase();
    if (!letter)
        return undefined;
    if (!options.some((one) => one.key === letter))
        throw new Refused(`There is no option ${letter} to recommend.`);
    return letter;
}
// What a person adds themselves (a prototype is made for them, and stays the
// kobold's to take off).
const THEIRS = new Set(["note", "picture", "link", "sketch", "mark"]);
// What a person put on the board is theirs: the kobold may move it, never
// change or remove it.
function theirs(board, act) {
    if (act.act !== "change" && act.act !== "remove")
        return;
    const thing = thingOf(board, act.id);
    if (thing.by === "person" && THEIRS.has(thing.kind))
        throw new Refused(`${act.id} is the team's own: you may move it, never change or remove it.`);
}
export function applyAct(board, act, by) {
    if (by === "kobold")
        theirs(board, act);
    return applied(board, act, by);
}
function applied(board, act, by) {
    switch (act.act) {
        case "note":
            return added(board, {
                id: newId(board, "note"),
                kind: "note",
                ...fresh(by),
                text: act.text.trim(),
            }, act);
        case "diagram":
            return added(board, {
                id: newId(board, "diagram"),
                kind: "diagram",
                ...fresh(by),
                title: act.title.trim(),
                diagram: act.diagram,
            }, act);
        case "choice":
            return added(board, newChoice(board, act, by), act);
        case "change":
            return changed(board, act);
        case "remove":
            return { board: withoutThing(board, act.id), said: `Removed ${act.id}.` };
        case "link":
            return {
                board: linked(board, act.from, act.to, act.label?.trim() ?? ""),
                said: `Linked ${act.from} → ${act.to}.`,
            };
        case "unlink":
            return {
                board: unlinked(board, act.from, act.to),
                said: `Unlinked ${act.from} → ${act.to}.`,
            };
        case "agree":
            return agreedAct(board, act);
        default:
            return placedOrChosen(board, act);
    }
}
function placedOrChosen(board, act) {
    const thing = thingOf(board, act.id);
    if (act.act === "show")
        return shown(board, thing, act.variant);
    if (act.act === "move")
        return {
            board: withThing(board, { ...thing, place: { x: act.x, y: act.y } }),
            said: `Moved ${act.id}.`,
        };
    if (thing.kind !== "choice")
        throw new Refused(`${act.id} is not a choice.`);
    if (act.option && !thing.options.some((one) => one.key === act.option))
        throw new Refused(`${act.id} has no option ${act.option}.`);
    return {
        board: withThing(board, { ...thing, chosen: act.option }),
        said: act.option
            ? `Chose ${act.option} on ${act.id}.`
            : `Took back the choice on ${act.id}.`,
    };
}
// A thing agreed, or a sketch again; a prototype agreed with a named
// variant shows that variant first.
function agreedAct(board, act) {
    const on = act.variant
        ? shown(board, thingOf(board, act.id), act.variant).board
        : board;
    const named = act.variant ? ` with variant ${act.variant}` : "";
    const now = act.agreed ? "agreed" + named : "a sketch";
    return {
        board: agreed(on, act.id, act.agreed),
        said: `${act.id} is ${now}.`,
    };
}
// A prototype's variant shown on the board (and agreed with it).
function shown(board, thing, variant) {
    if (thing.kind !== "prototype" ||
        !thing.variants?.some((one) => one.key === variant))
        throw new Refused(`${thing.id} has no variant ${variant}.`);
    return {
        board: withThing(board, { ...thing, variant }),
        said: `Showing variant ${variant} of ${thing.id}.`,
    };
}
// What a person did, in words the kobold hears with their next message.
export function personWords(act, board) {
    const name = (id) => {
        const thing = board.things.find((one) => one.id === id);
        return thing ? `${thing.kind} ${id}` : id;
    };
    switch (act.act) {
        case "agree":
            return `marked ${name(act.id)} ${act.agreed ? "agreed" : "a sketch"}`;
        case "choose":
            return act.option
                ? `chose ${act.option} on ${name(act.id)}`
                : `took back the choice on ${name(act.id)}`;
        case "move":
            return `moved ${name(act.id)}`;
        case "show":
            return `looked at variant ${act.variant} of ${name(act.id)}`;
        case "remove":
            return `removed ${act.id}`;
        default:
            return `changed ${act.act === "change" ? name(act.id) : "the board"}`;
    }
}
